        >
          <Zap className="w-3 h-3" />
          {showSimulator ? '收起模拟器' : 'CES 模拟器'}
        </button>
      </div>

      {/* 主体网格 */}
      <div className="p-5 grid grid-cols-1 md:grid-cols-2 gap-5">
