                className={`px-2 py-0.5 rounded-md text-[11px] font-medium border ${tagColor}`}
              >
                🔍 {kw}
                <span className="ml-1 text-[9px] opacity-70">{isCore ? '核心' : isLongTail ? '长尾' : '中尾'}</span>
