import { chromium } from 'playwright'
import fs from 'fs'

const SCREENSHOTS_DIR = '/tmp/ripple_screenshots'
fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true })

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  locale: 'zh-CN',
  deviceScaleFactor: 2,
})
const page = await context.newPage()

const errors = []
page.on('pageerror', (err) => errors.push(`PAGE ERROR: ${err.message}`))
page.on('console', (msg) => {
  if (msg.type() === 'error') {
    const text = msg.text()
    // skip common noisy errors not related to our code
    if (text.includes('favicon')) return
    if (text.includes('Failed to load resource')) return
    errors.push(`CONSOLE: ${text}`)
  }
})

console.log('🌐 Opening localhost:5173...')
await page.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
await page.waitForTimeout(2500)

console.log('📸 [1/8] Hero screenshot')
await page.screenshot({ path: `${SCREENSHOTS_DIR}/01_hero.png`, fullPage: false })

// 滚动到最底部展示完整 hero
await page.evaluate(() => window.scrollTo(0, 200))
await page.waitForTimeout(500)
await page.screenshot({ path: `${SCREENSHOTS_DIR}/02_hero_demos.png`, fullPage: false })

// 点击 6 个 demo 中的第一个 (campus-ai-notes)
const demoButtons = await page.$$('button[class*="grid-cols"] >> button, .grid button')
console.log(`📊 Found ${demoButtons.length} demo buttons (or grid items)`)

const demos = [
  { id: 'campus-ai-notes', text: 'AI 学习笔记' },
  { id: 'campus-food-blog', text: '美食' },
  { id: 'campus-kaoyan', text: '考研' },
  { id: 'ai-tool-review', text: 'AI 工具' },
  { id: 'graduation-content', text: '毕业季' },
  { id: 'dorm-budget', text: '宿舍' },
]

for (let i = 0; i < demos.length; i++) {
  const demo = demos[i]
  console.log(`\n📸 [Demo ${i + 1}/${demos.length}] ${demo.text}`)

  // 回到首页
  if (i > 0) {
    // 清除会话进入新对话
    await page.evaluate(() => {
      window.localStorage.clear()
      window.location.reload()
    })
    await page.waitForLoadState('networkidle')
    await page.waitForTimeout(1500)
  }

  // 找到 demo 按钮（通过包含的关键文字）
  const allButtons = await page.$$('button')
  let clicked = false
  for (const btn of allButtons) {
    const text = await btn.textContent()
    if (text && text.includes(demo.text)) {
      const isVisible = await btn.isVisible()
      if (isVisible) {
        try {
          await btn.click({ timeout: 5000 })
          clicked = true
          console.log(`   ✓ Clicked button matching "${demo.text}"`)
          break
        } catch {}
      }
    }
  }

  if (!clicked) {
    console.log(`   ✗ Could not find/click demo for "${demo.text}"`)
    continue
  }

  // 等待内容渲染
  await page.waitForTimeout(2500)
  await page.screenshot({ path: `${SCREENSHOTS_DIR}/${String(i + 3).padStart(2, '0')}_demo_${demo.id}_top.png`, fullPage: false })

  // 完整截图
  await page.screenshot({ path: `${SCREENSHOTS_DIR}/${String(i + 3).padStart(2, '0')}_demo_${demo.id}_full.png`, fullPage: true })
}

if (errors.length > 0) {
  console.log('\n❌ Errors detected:')
  errors.forEach(e => console.log('  ', e))
} else {
  console.log('\n✅ No errors detected')
}

await browser.close()
console.log(`\n📁 Screenshots saved to ${SCREENSHOTS_DIR}`)

import { chromium } from 'playwright'
import fs from 'fs'

const SCREENSHOTS_DIR = '/tmp/ripple_screenshots_v2'
fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true })

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  locale: 'zh-CN',
  deviceScaleFactor: 2,
})
const page = await context.newPage()

const errors = []
page.on('pageerror', (err) => errors.push(`PAGE ERROR: ${err.message}`))
page.on('console', (msg) => {
  if (msg.type() === 'error') {
    const text = msg.text()
    if (text.includes('favicon') || text.includes('Failed to load resource')) return
    errors.push(`CONSOLE: ${text}`)
  }
})

console.log('🌐 Opening localhost:5173...')
await page.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
await page.waitForTimeout(2500)

// 关闭 sidebar 如果它是开的（避免干扰点击）
console.log('📸 [1] Hero')
await page.screenshot({ path: `${SCREENSHOTS_DIR}/01_hero.png`, fullPage: true })

// 6 个 demo 案例的精确 title（来自 demoCases.ts）
const demos = [
  { id: 'campus-ai-notes', title: '大学生AI学习笔记双平台定位' },
  { id: 'campus-food-blog', title: '校园美食公众号AI日更' },
  { id: 'campus-kaoyan', title: '考研经验搜一搜关键词布局' },
  { id: 'ai-tool-review', title: '学生AI工具测评冷启动' },
  { id: 'graduation-content', title: '毕业季全平台分发策略' },
  { id: 'dorm-budget', title: '宿舍好物博主AI提效' },
]

for (let i = 0; i < demos.length; i++) {
  const demo = demos[i]
  console.log(`\n📸 [Demo ${i + 1}/${demos.length}] ${demo.title}`)

  // 总是回到首页
  await page.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
  await page.waitForTimeout(1500)

  // 精确通过 demo title 匹配按钮（在主区，不在 sidebar）
  // demo 卡片按钮的特征：含有 "即时" 徽章 + title text
  const clicked = await page.evaluate((title) => {
    const buttons = document.querySelectorAll('main button')
    for (const btn of buttons) {
      const text = btn.textContent || ''
      if (text.includes(title) && text.includes('即时')) {
        ;(btn as HTMLButtonElement).click()
        return true
      }
    }
    // fallback: any button containing title (excluding sidebar)
    const allBtns = document.querySelectorAll('button')
    for (const btn of allBtns) {
      const text = btn.textContent || ''
      if (text.includes(title) && !btn.closest('[class*="Sidebar"]')) {
        ;(btn as HTMLButtonElement).click()
        return true
      }
    }
    return false
  }, demo.title)

  if (!clicked) {
    console.log(`   ✗ Could not click demo "${demo.title}"`)
    continue
  }

  console.log(`   ✓ Clicked. Waiting for content...`)
  await page.waitForTimeout(3500)

  // 滚动到顶部截图
  await page.evaluate(() => window.scrollTo(0, 0))
  await page.waitForTimeout(300)
  await page.screenshot({ path: `${SCREENSHOTS_DIR}/${String(i + 2).padStart(2, '0')}_${demo.id}_01_top.png`, fullPage: false })

  // 完整长截图
  await page.screenshot({ path: `${SCREENSHOTS_DIR}/${String(i + 2).padStart(2, '0')}_${demo.id}_02_full.png`, fullPage: true })
}

if (errors.length > 0) {
  console.log('\n❌ Errors detected:')
  errors.forEach(e => console.log('  ', e))
} else {
  console.log('\n✅ No errors detected')
}

await browser.close()
console.log(`\n📁 Screenshots saved to ${SCREENSHOTS_DIR}`)

