import { chromium } from 'playwright'
import fs from 'fs'

const SCREENSHOTS_DIR = '/tmp/ripple_screenshots_v3'
fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true })

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  locale: 'zh-CN',
  deviceScaleFactor: 2,
})
const page = await context.newPage()

const errors = []
page.on('pageerror', (err) => errors.push(`PAGE ERROR: ${err.message}`))
page.on('console', (msg) => {
  if (msg.type() === 'error') {
    const text = msg.text()
    if (text.includes('favicon') || text.includes('Failed to load resource')) return
    errors.push(`CONSOLE: ${text}`)
  }
})

const demos = [
  { id: 'campus-ai-notes', title: '大学生AI学习笔记双平台定位' },
  { id: 'campus-food-blog', title: '校园美食公众号AI日更' },
  { id: 'campus-kaoyan', title: '考研经验搜一搜关键词布局' },
  { id: 'ai-tool-review', title: '学生AI工具测评冷启动' },
  { id: 'graduation-content', title: '毕业季全平台分发策略' },
  { id: 'dorm-budget', title: '宿舍好物博主AI提效' },
]

for (let i = 0; i < demos.length; i++) {
  const demo = demos[i]
  console.log(`\n📸 [${i + 1}/${demos.length}] ${demo.title}`)

  await page.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
  await page.waitForTimeout(1500)

  const clicked = await page.evaluate((title) => {
    const buttons = document.querySelectorAll('main button')
    for (const btn of buttons) {
      const text = btn.textContent || ''
      if (text.includes(title) && text.includes('即时')) {
        btn.click()
        return true
      }
    }
    return false
  }, demo.title)

  if (!clicked) { console.log(`   ✗ Click failed`); continue }
  await page.waitForTimeout(3500)

  // 找到滚动容器
  const scrollerInfo = await page.evaluate(() => {
    const scroller = document.querySelector('main .overflow-y-auto')
    if (!scroller) return null
    return { height: scroller.scrollHeight, viewport: scroller.clientHeight }
  })

  if (!scrollerInfo) {
    console.log(`   ✗ No scroller found`)
    continue
  }
  console.log(`   📏 scrollHeight=${scrollerInfo.height}, viewport=${scrollerInfo.viewport}`)

  // 滚动并截图：每屏一张
  const numScreens = Math.ceil(scrollerInfo.height / scrollerInfo.viewport)
  for (let s = 0; s < numScreens && s < 5; s++) {
    await page.evaluate((y) => {
      const scroller = document.querySelector('main .overflow-y-auto')
      if (scroller) scroller.scrollTo({ top: y, behavior: 'instant' })
    }, s * scrollerInfo.viewport)
    await page.waitForTimeout(500)
    await page.screenshot({
      path: `${SCREENSHOTS_DIR}/${String(i + 1).padStart(2, '0')}_${demo.id}_scroll${s}.png`,
      fullPage: false,
    })
  }
}

if (errors.length > 0) {
  console.log('\n❌ Errors:')
  errors.forEach(e => console.log('  ', e))
} else {
  console.log('\n✅ No errors')
}

await browser.close()
console.log(`\n📁 ${SCREENSHOTS_DIR}`)

