import { chromium } from 'playwright'
import fs from 'fs'

const SCREENSHOTS_DIR = '/tmp/ripple_final_test'
fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true })

const browser = await chromium.launch({ headless: true })

// 桌面 1440x900
console.log('🖥️  Desktop 1440x900')
const desktopCtx = await browser.newContext({ viewport: { width: 1440, height: 900 }, locale: 'zh-CN', deviceScaleFactor: 2 })
const desktopPage = await desktopCtx.newPage()
const errors = []
desktopPage.on('pageerror', (err) => errors.push(`DESKTOP PAGE ERROR: ${err.message}`))
desktopPage.on('console', (msg) => {
  if (msg.type() === 'error') {
    const text = msg.text()
    if (text.includes('favicon') || text.includes('Failed to load resource')) return
    errors.push(`DESKTOP CONSOLE: ${text}`)
  }
})

await desktopPage.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
await desktopPage.waitForTimeout(2000)

await desktopPage.screenshot({ path: `${SCREENSHOTS_DIR}/desktop_01_hero.png`, fullPage: false })

// 测 KOC 阶段诊断模态
console.log('   🩺 Open KOC Stage Diagnose')
await desktopPage.evaluate(() => {
  const buttons = document.querySelectorAll('button')
  for (const btn of buttons) {
    if ((btn.textContent || '').includes('KOC 阶段诊断')) { btn.click(); return }
  }
})
await desktopPage.waitForTimeout(800)
await desktopPage.screenshot({ path: `${SCREENSHOTS_DIR}/desktop_02_stage_modal_initial.png`, fullPage: false })

// 拖动滑块
await desktopPage.evaluate(() => {
  const sliders = document.querySelectorAll('input[type="range"]')
  if (sliders.length >= 1) {
    const s = sliders[0]
    s.value = '3500'
    s.dispatchEvent(new Event('input', { bubbles: true }))
    s.dispatchEvent(new Event('change', { bubbles: true }))
  }
  if (sliders.length >= 2) {
    const s = sliders[1]
    s.value = '35'
    s.dispatchEvent(new Event('input', { bubbles: true }))
    s.dispatchEvent(new Event('change', { bubbles: true }))
  }
})
await desktopPage.waitForTimeout(300)
await desktopPage.evaluate(() => {
  const buttons = document.querySelectorAll('button')
  for (const btn of buttons) {
    if ((btn.textContent || '').includes('诊断我的账号阶段')) { btn.click(); return }
  }
})
await desktopPage.waitForTimeout(800)
await desktopPage.screenshot({ path: `${SCREENSHOTS_DIR}/desktop_03_stage_diagnosed.png`, fullPage: false })
await desktopPage.screenshot({ path: `${SCREENSHOTS_DIR}/desktop_04_stage_diagnosed_full.png`, fullPage: true })

// 关闭模态
await desktopPage.keyboard.press('Escape')
await desktopPage.waitForTimeout(300)
// 通过点击背景关闭
await desktopPage.evaluate(() => {
  const buttons = document.querySelectorAll('button')
  for (const btn of buttons) {
    const html = btn.innerHTML
    if (html.includes('lucide-x') && btn.closest('.fixed')) { btn.click(); return }
  }
})
await desktopPage.waitForTimeout(600)

// 移动端测试 375x812 (iPhone X)
console.log('\n📱 Mobile 375x812')
const mobileCtx = await browser.newContext({
  viewport: { width: 375, height: 812 },
  locale: 'zh-CN',
  deviceScaleFactor: 3,
  isMobile: true,
  hasTouch: true,
})
const mobilePage = await mobileCtx.newPage()
mobilePage.on('pageerror', (err) => errors.push(`MOBILE PAGE ERROR: ${err.message}`))

await mobilePage.goto('http://localhost:5173', { waitUntil: 'networkidle', timeout: 30000 })
await mobilePage.waitForTimeout(2000)

await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_01_hero.png`, fullPage: false })
await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_02_hero_full.png`, fullPage: true })

// 点击 demo
console.log('   👆 Click demo on mobile')
await mobilePage.evaluate(() => {
  const buttons = document.querySelectorAll('button')
  for (const btn of buttons) {
    const text = btn.textContent || ''
    if (text.includes('校园美食公众号AI日更')) { btn.click(); return }
  }
})
await mobilePage.waitForTimeout(3500)
await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_03_demo_top.png`, fullPage: false })

// 滚动到 AgentRoundtable
await mobilePage.evaluate(() => {
  const scroller = document.querySelector('main .overflow-y-auto')
  if (scroller) scroller.scrollTo({ top: 600 })
})
await mobilePage.waitForTimeout(500)
await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_04_agent.png`, fullPage: false })

// 滚动到 ViralScoreDashboard
await mobilePage.evaluate(() => {
  const scroller = document.querySelector('main .overflow-y-auto')
  if (scroller) scroller.scrollTo({ top: 1200 })
})
await mobilePage.waitForTimeout(500)
await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_05_ces.png`, fullPage: false })

// 滚动到 WeChat panel
await mobilePage.evaluate(() => {
  const scroller = document.querySelector('main .overflow-y-auto')
  if (scroller) scroller.scrollTo({ top: 2000 })
})
await mobilePage.waitForTimeout(500)
await mobilePage.screenshot({ path: `${SCREENSHOTS_DIR}/mobile_06_wechat.png`, fullPage: false })

if (errors.length > 0) {
  console.log('\n❌ Errors detected:')
  errors.forEach(e => console.log('  ', e))
} else {
  console.log('\n✅ No errors detected')
}

await browser.close()
console.log(`\n📁 ${SCREENSHOTS_DIR}`)
